/**
 * UI/UX templates for vendor storefronts
 *
 * This interface was referenced by `Config`'s JSON-Schema
 * via the `definition` "vendor-templates".
 */
export interface VendorTemplate {
  id: string;
  /**
   * Template name (e.g., 'Modern Minimal', 'Classic Elegance')
   */
  name: string;
  /**
   * URL-friendly identifier (auto-generated from name)
   */
  slug: string;
  /**
   * Template description shown to vendors
   */
  description?: string | null;
  /**
   * Screenshot/preview image of the template (recommended: 1920x1080px)
   */
  previewImage?: (string | null) | Media;
  /**
   * Small thumbnail for template selection UI (recommended: 400x300px)
   */
  thumbnailImage?: (string | null) | Media;
  /**
   * Visual mood for filtering (minimal, elegant, bold, etc.)
   */
  category: 'minimal' | 'elegant' | 'bold' | 'colorful' | 'classic';
  /**
   * Industry vertical for vendor theme discovery
   */
  industry:
    | 'general'
    | 'fashion-boutique'
    | 'ethnic-apparel'
    | 'ethnic-heritage'
    | 'luxury'
    | 'catalog'
    | 'neighborhood-retail'
    | 'marketplace'
    | 'social-resale'
    | 'home-lifestyle'
    | 'wellness'
    | 'events-promo';
  /**
   * Featured themes appear in the main vendor theme picker. Non-featured themes remain available to vendors already using them.
   */
  isFeatured?: boolean | null;
  /**
   * Lower numbers appear first in the vendor theme picker
   */
  sortOrder?: number | null;
  /**
   * Site-wide default template for new vendors. Only one template can be default; checking this unchecks any other default.
   */
  isDefault?: boolean | null;
  /**
   * Whether template is available for selection
   */
  isActive?: boolean | null;
  /**
   * Template version number
   */
  version?: string | null;
  /**
   * Template creator/author
   */
  author?: string | null;
  /**
   * Template configuration schema (colors, fonts, spacing, layout, components)
   */
  templateConfig:
    | {
        [k: string]: unknown;
      }
    | unknown[]
    | string
    | number
    | boolean
    | null;
  /**
   * CSS custom properties/variables for the template
   */
  cssVariables:
    | {
        [k: string]: unknown;
      }
    | unknown[]
    | string
    | number
    | boolean
    | null;
  /**
   * Component structure mapping (which component variants to use)
   */
  componentMapping:
    | {
        [k: string]: unknown;
      }
    | unknown[]
    | string
    | number
    | boolean
    | null;
  updatedAt: string;
  createdAt: string;
}
